import {predict,validate} from './model.js';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Number(n).toLocaleString('en-US');
const pct=(p,n=1)=>(p*100).toFixed(n)+'%';
const icons={grid:'<rect x="3" y="3" width="6" height="6" rx="1"/><rect x="13" y="3" width="6" height="6" rx="1"/><rect x="3" y="13" width="6" height="6" rx="1"/><rect x="13" y="13" width="6" height="6" rx="1"/>',list:'<rect x="3" y="3" width="16" height="16" rx="2"/><path d="M7 8h8M7 12h8M7 16h5"/>',users:'<circle cx="9" cy="7" r="3"/><path d="M3 19v-2a6 6 0 0112 0v2M15 4a3 3 0 010 6M18 13a5 5 0 012 4v2"/>',spark:'<path d="m12 2 2.3 6.7L21 11l-6.7 2.3L12 20l-2.3-6.7L3 11l6.7-2.3ZM3 3v4M1 5h4"/>',chart:'<path d="M3 3v16h17M7 15v-4M12 15V7M17 15V4"/>',download:'<path d="M11 3v11m-4-4 4 4 4-4M3 15v4h16v-4"/>',arrow:'<path d="M4 11h14m-5-5 5 5-5 5"/>',search:'<circle cx="9" cy="9" r="6"/><path d="m14 14 6 6"/>',calendar:'<rect x="3" y="5" width="16" height="15" rx="2"/><path d="M7 2v6M15 2v6M3 10h16"/>',clock:'<circle cx="11" cy="11" r="8"/><path d="M11 6v5l3 2"/>',target:'<circle cx="11" cy="11" r="8"/><circle cx="11" cy="11" r="4"/><circle cx="11" cy="11" r=".5"/>',swap:'<path d="M3 7h16m-4-4 4 4-4 4M19 16H3m4-4-4 4 4 4"/>',check:'<path d="m4 11 5 5L19 5"/>'};
const icon=name=>`<svg width="22" height="22" viewBox="0 0 22 22" fill="none" stroke="currentColor" stroke-width="1.45" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]??icons.grid}</svg>`;
$$('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));
const names={overview:'Overview',matches:'Match explorer',players:'Players',predict:'Prediction lab',research:'Research & data'};
const state={page:'overview',match:{q:'',tour:'all',surface:'all',status:'all',sort:'date',page:1,size:25},player:{q:'',tour:'all',min:0,sort:'wins',page:1,size:25},downloadCategory:'all',scenario:null,fixture:3};
let D={};let activeMatches=[];let activePlayers=[];let scenarioOutput=null;
const main=$('#main');
$('.skip').addEventListener('click',event=>{event.preventDefault();main.focus();main.scrollIntoView({block:'start'});});
function head(kicker,title,subtitle,action=''){return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`;}
function notify(message){const e=$('#toast');e.textContent=message;e.classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>e.classList.remove('show'),2500);}
function download(name,content,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function csv(rows){if(!rows.length)return '';const keys=Object.keys(rows[0]);const cell=v=>'"'+String(v??'').replaceAll('"','""')+'"';return [keys.map(cell).join(','),...rows.map(r=>keys.map(k=>cell(r[k])).join(','))].join('\r\n');}
const badge=t=>`<span class="tag ${t==='WTA'?'wta':''}">${esc(t)}</span>`;
function fixtureCard(f,i){const pa=Number(f.p_a_strength);return `<article class="fixture-card"><div class="fixture-meta"><span>${badge(f.tour)} &nbsp; ${esc(f.event)} · QF</span><span>23 OCT</span></div><div class="player-line ${pa>=.5?'favorite':''}"><span class="player-dot"></span><span>${esc(f.name_a)}</span><b class="mono">${pct(pa)}</b></div><div class="player-line ${pa<.5?'favorite':''}"><span class="player-dot"></span><span>${esc(f.name_b)}</span><b class="mono">${pct(1-pa)}</b></div><div class="prob-track" aria-label="${esc(f.name_a)} ${pct(pa)}, ${esc(f.name_b)} ${pct(1-pa)}"><span style="width:${pa*100}%"></span></div><div class="fixture-footer"><span>Baseline win probability</span><button class="text-action" data-fixture="${i}">Analyze match ${icon('arrow')}</button></div></article>`;}
function overview(){
 main.innerHTML=head('THE 2026 SEASON','A clearer view of the match.','Explore the records. Understand the workload. Test the probabilities.',`<span class="date-chip">${icon('calendar')} Jan - Oct 2026</span>`)+
 `<div class="stats-grid"><div class="stat"><div class="stat-top">Match records ${icon('list')}</div><div class="stat-value">5,054</div><div class="stat-bottom"><b>ATP + WTA</b> · Deduplicated snapshot</div></div><div class="stat"><div class="stat-top">Completed matches ${icon('check')}</div><div class="stat-value">4,874</div><div class="stat-bottom">Standard completed singles scores</div></div><div class="stat"><div class="stat-top">Players represented ${icon('users')}</div><div class="stat-value">${fmt(D.players.length)}</div><div class="stat-bottom">In standard completed matches</div></div><div class="stat"><div class="stat-top">Test accuracy ${icon('target')}</div><div class="stat-value">60.9<span style="font-size:20px">%</span></div><div class="stat-bottom"><b>174 matches</b> · Independent test set</div></div></div>
 <section class="insight-banner"><div><div class="eyebrow">THE WORKLOAD QUESTION</div><h2>More court time. Lower win odds.<br>But a better prediction? Not yet.</h2><p>Prior match duration has a negative adjusted association with winning. Adding workload did not deliver a reliable improvement on the independent test set.</p><a href="#research">Explore the research ${icon('arrow')}</a></div><div class="court-art" aria-hidden="true"><div class="court-lines"></div><div class="court-ball"></div></div></section>
 <div class="dashboard-grid"><section><div class="section-head"><div><h2>The next matchups</h2><p>Frozen forecasts · 23 October 2026</p></div><a href="#predict" class="subtle-link">Open prediction lab ↗</a></div><div class="fixtures-grid">${D.fixtures.map(fixtureCard).join('')}</div><p class="footnote">Pre-match estimates based on history through 22 October. These forecasts are conditional on normal match completion and are not live updates.</p></section>
 <aside class="coverage-aside"><div class="panel"><h3>Inside the snapshot</h3><p class="subtext">Standard completed matches</p><div class="coverage-item"><div class="coverage-label"><span>${badge('ATP')}</span><b>2,548</b></div><div class="coverage-track"><span style="width:100%"></span></div></div><div class="coverage-item"><div class="coverage-label"><span>${badge('WTA')}</span><b>2,326</b></div><div class="coverage-track"><span style="width:${2326/2548*100}%"></span></div></div><div class="mini-stats"><div><strong>111<small> min</small></strong><small>ATP median duration</small></div><div><strong>99<small> min</small></strong><small>WTA median duration</small></div></div><p class="footnote">Durations available for 2,467 ATP and 2,042 WTA matches.</p></div><div class="source-box"><strong>Traceable from source to forecast</strong>Match history from TennisMyLife. Fixtures and an official API demo checked with TennisStats.<br><a class="text-action" href="#research">See sources & download data ${icon('arrow')}</a></div></aside></div>`;
 bindFixtures();
}
function bindFixtures(){ $$('[data-fixture]',main).forEach(b=>b.addEventListener('click',()=>{loadFixture(Number(b.dataset.fixture));location.hash='predict';if(state.page==='predict')render();})); }
function options(items,value){return items.map(x=>{const [v,label]=Array.isArray(x)?x:[x,x];return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(label)}</option>`;}).join('');}
function searchBox(id,placeholder,value){return `<div class="search">${icon('search')}<input id="${id}" type="search" placeholder="${placeholder}" value="${esc(value)}" aria-label="${placeholder}"></div>`;}
function matches(){
 const s=state.match;
 main.innerHTML=head('MATCH EXPLORER','Every record. A closer look.','Search the full 2026 snapshot, inspect all source fields, and export the records you need.',`<button id="export-matches" class="button secondary">${icon('download')}Export CSV</button>`)+
 `<div class="note-strip">Source dates may be match dates or tournament start dates. They should not be used to calculate exact rest time. This snapshot is not a complete 2026 season.</div>
 <div class="toolbar">${searchBox('match-search','Search player, tournament or country…',s.q)}<select id="match-tour" aria-label="Tour">${options([['all','All tours'],'ATP','WTA'],s.tour)}</select><select id="match-surface" aria-label="Surface">${options([['all','All surfaces'],'Hard','Clay','Grass','Carpet'],s.surface)}</select><select id="match-status" aria-label="Record status">${options([['all','All records'],['completed','Standard completed'],['eligible','Model eligible'],['other','Non-standard / unplayed']],s.status)}</select><select id="match-sort" aria-label="Sort matches">${options([['date','Newest source date'],['minutes','Longest duration'],['event','Tournament A-Z']],s.sort)}</select></div>
 <div class="data-shell"><div class="table-info" id="match-info"></div><div class="table-scroll"><table><thead><tr><th>Source date</th><th>Tournament</th><th>Winner / loser</th><th>Score</th><th>Minutes</th><th>Analysis</th><th><span class="sr-label">Details</span></th></tr></thead><tbody id="match-body"></tbody></table></div><div class="pagination" id="match-pagination"></div></div>`;
 updateMatches();
 $('#match-search').addEventListener('input',e=>{s.q=e.target.value;s.page=1;updateMatches();});
 for(const key of ['tour','surface','status','sort'])$('#match-'+key).addEventListener('change',e=>{s[key]=e.target.value;s.page=1;updateMatches();});
 $('#export-matches').onclick=()=>{if(!activeMatches.length)return notify('No records match these filters.');download('CourtEdge_filtered_matches.csv',csv(activeMatches),'text/csv;charset=utf-8');notify(`${fmt(activeMatches.length)} records exported.`);};
}
function updateMatches(){
 const s=state.match,q=s.q.toLowerCase().trim();
 activeMatches=D.matches.filter(r=>(!q||`${r.winner_name} ${r.loser_name} ${r.tourney_name} ${r.winner_ioc} ${r.loser_ioc}`.toLowerCase().includes(q))&&(s.tour==='all'||r.tour===s.tour)&&(s.surface==='all'||r.surface===s.surface)&&(s.status==='all'||(s.status==='completed'&&r.valid_score)||(s.status==='eligible'&&r.analysis_eligible)||(s.status==='other'&&!r.valid_score)));
 activeMatches.sort((a,b)=>s.sort==='minutes'?(b.minutes??-1)-(a.minutes??-1):s.sort==='event'?a.tourney_name.localeCompare(b.tourney_name):String(b.source_date).localeCompare(String(a.source_date)));
 const start=(s.page-1)*s.size,rows=activeMatches.slice(start,start+s.size);
 $('#match-info').innerHTML=`<span><b>${fmt(activeMatches.length)}</b> records ${s.q||s.tour!=='all'||s.surface!=='all'||s.status!=='all'?'matching your filters':'in the snapshot'}</span><span>All original fields available in Details and CSV</span>`;
 $('#match-body').innerHTML=rows.length?rows.map((r,i)=>`<tr><td class="mono">${esc(r.source_date)}<small>${badge(r.tour)}</small></td><td><b>${esc(r.tourney_name)}</b><small>${esc(r.surface||'Unknown surface')} · ${esc(r.round)}</small></td><td class="text-wrap"><b><span class="win-mark">W</span>${esc(r.winner_name)}</b><small>vs ${esc(r.loser_name)}</small></td><td class="mono">${esc(r.score||'—')}</td><td class="mono">${r.minutes??'—'}</td><td>${r.analysis_eligible?'<span class="tag">Eligible</span>':r.valid_score?'<span class="tag surface">Outside sample</span>':'<span class="tag warning">Non-standard</span>'}</td><td><button class="text-action" data-details="${start+i}" aria-label="View ${esc(r.winner_name)} versus ${esc(r.loser_name)} details">View ↗</button></td></tr>`).join(''):'<tr><td colspan="7"><div class="empty"><strong>No matches found</strong>Try another player, tournament or filter.</div></td></tr>';
 pagination('match-pagination',s,activeMatches.length,updateMatches);
 $$('[data-details]').forEach(b=>b.onclick=()=>showMatch(activeMatches[Number(b.dataset.details)]));
}
function pagination(id,s,total,fn){const pages=Math.max(1,Math.ceil(total/s.size));const e=$('#'+id);e.innerHTML=`<span>${total?fmt((s.page-1)*s.size+1):0}-${fmt(Math.min(s.page*s.size,total))} of ${fmt(total)}</span><div><label>Rows <select aria-label="Rows per page">${options([25,50,100],s.size)}</select></label><button class="button small secondary prev" ${s.page<=1?'disabled':''}>Previous</button><span>${s.page} / ${pages}</span><button class="button small secondary next" ${s.page>=pages?'disabled':''}>Next</button></div>`;$('.prev',e).onclick=()=>{s.page--;fn();};$('.next',e).onclick=()=>{s.page++;fn();};$('select',e).onchange=event=>{s.size=Number(event.target.value);s.page=1;fn();};}
const fieldLabel=k=>k.replace(/^w_/,'Winner ').replace(/^l_/,'Loser ').replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());
function showMatch(r){
 $('#dialog-content').innerHTML=`<div class="eyebrow">${esc(r.tour)} · ${esc(r.tourney_name)} · ${esc(r.round)}</div><h2 style="padding-right:20px">${esc(r.winner_name)} vs ${esc(r.loser_name)}</h2><p style="margin:10px 0;font-size:12px">Winner: ${esc(r.winner_name)} · ${esc(r.score)} · ${r.minutes??'Unknown'} minutes</p><div class="note-strip">${r.analysis_eligible?'Eligible for the workload modeling sample.':r.valid_score?'Completed score, but outside the model sample because required prior history or other predictors were not complete.':'Non-standard or unplayed score; excluded from the completed-match model.'} Source date: ${esc(r.source_date)}. See the exclusion CSV for per-match reasons.</div><div class="detail-grid">${Object.entries(r).map(([k,v])=>`<div><small>${esc(fieldLabel(k))}</small><b>${esc(v===null?'Not available':v)}</b></div>`).join('')}</div>`;
 $('#detail-dialog').showModal();
}
function players(){
 const s=state.player;
 main.innerHTML=head('PLAYER DIRECTORY','The players behind the numbers.','Season records from standard completed singles. Last recorded rankings are historical snapshot values.',`<a class="button secondary" href="downloads/player_statistics_2026.csv" download>${icon('download')}Player CSV</a>`)+
 `<div class="toolbar">${searchBox('player-search','Search a player or country…',s.q)}<select id="player-tour" aria-label="Player tour">${options([['all','All tours'],'ATP','WTA'],s.tour)}</select><select id="player-min" aria-label="Minimum matches">${options([[0,'Any match count'],[10,'10+ matches'],[25,'25+ matches'],[50,'50+ matches']],s.min)}</select><select id="player-sort" aria-label="Sort players">${options([['wins','Most wins'],['win_rate','Highest win rate'],['matches','Most matches'],['recorded_minutes','Most recorded minutes'],['player','Name A-Z']],s.sort)}</select></div>
 <div class="data-shell"><div class="table-info" id="player-info"></div><div class="table-scroll"><table><thead><tr><th>Player</th><th>Tour</th><th>Matches</th><th>Wins / losses</th><th>Win rate</th><th>Recorded minutes</th><th>Last rank</th><th>Records</th></tr></thead><tbody id="player-body"></tbody></table></div><div class="pagination" id="player-pagination"></div></div><p class="footnote">Win rates describe this source snapshot, not model probabilities. Minutes exclude missing durations; data coverage is shown below each total. Rankings may differ across dates and sources.</p>`;
 updatePlayers();$('#player-search').oninput=e=>{s.q=e.target.value;s.page=1;updatePlayers();};for(const key of ['tour','min','sort'])$('#player-'+key).onchange=e=>{s[key]=key==='min'?Number(e.target.value):e.target.value;s.page=1;updatePlayers();};
}
function updatePlayers(){const s=state.player,q=s.q.toLowerCase().trim();activePlayers=D.players.filter(p=>(!q||`${p.player} ${p.country}`.toLowerCase().includes(q))&&(s.tour==='all'||p.tour===s.tour)&&p.matches>=s.min);activePlayers.sort((a,b)=>s.sort==='player'?a.player.localeCompare(b.player):b[s.sort]-a[s.sort]||b.matches-a.matches);const rows=activePlayers.slice((s.page-1)*s.size,s.page*s.size);$('#player-info').innerHTML=`<span><b>${fmt(activePlayers.length)}</b> players</span><span>Standard completed matches only</span>`;$('#player-body').innerHTML=rows.length?rows.map(p=>`<tr><td><b>${esc(p.player)}</b><small>${esc(p.country)}</small></td><td>${badge(p.tour)}</td><td class="mono">${p.matches}</td><td class="mono">${p.wins} / ${p.matches-p.wins}</td><td class="mono"><b>${pct(p.win_rate)}</b></td><td class="mono">${fmt(p.recorded_minutes)}<small>${p.duration_available} / ${p.matches} durations</small></td><td class="mono">${p.rank?'#'+p.rank:'—'}<small>${esc(p.rank_date)}</small></td><td><button class="text-action" data-player-matches="${esc(p.key)}">View matches ↗</button></td></tr>`).join(''):'<tr><td colspan="8"><div class="empty"><strong>No players found</strong>Change the search or minimum match count.</div></td></tr>';pagination('player-pagination',s,activePlayers.length,updatePlayers);$$('[data-player-matches]').forEach(b=>b.onclick=()=>{const p=D.players.find(x=>x.key===b.dataset.playerMatches);state.match={q:p.player,tour:p.tour,surface:'all',status:'completed',sort:'date',page:1,size:25};location.hash='matches';});}
function loadFixture(i){const f=D.fixtures[i];state.fixture=i;state.scenario={tour:f.tour,surface:'Hard',bestOf:3,round:'QF',a:{name:f.name_a,rank:f.rank_a,age:f.age_a,qualifier:!!f.qualifier_a,minutes:Math.round(f.prior_hours_a*60),matches:f.prior_matches_a},b:{name:f.name_b,rank:f.rank_b,age:f.age_b,qualifier:!!f.qualifier_b,minutes:Math.round(f.prior_hours_b*60),matches:f.prior_matches_b}};}
function playerForm(side){const s=state.scenario[side],cap=side.toUpperCase();return `<div class="player-form"><div class="player-form-title"><span class="avatar">${cap}</span> PLAYER ${cap}</div><div class="field"><label for="name-${side}">Player name</label><input id="name-${side}" list="player-options" value="${esc(s.name)}" placeholder="Search or enter a player" autocomplete="off"><small id="profile-${side}">Use verified pre-match rank and age.</small></div><div class="field-grid"><div class="field"><label for="rank-${side}">Pre-match rank</label><input id="rank-${side}" type="number" min="1" max="3000" step="1" value="${s.rank??''}"></div><div class="field"><label for="age-${side}">Age</label><input id="age-${side}" type="number" min="13" max="60" step=".001" value="${s.age??''}"></div></div><div class="field" style="margin-top:14px"><label for="qualifier-${side}">Entry status</label><select id="qualifier-${side}">${options([[0,'Direct / other entry'],[1,'Qualifier / lucky loser']],s.qualifier?1:0)}</select></div><div class="workload-divider">PRIOR PLAY IN THIS EVENT</div><div class="field-grid"><div class="field"><label for="minutes-${side}">Minutes played</label><input id="minutes-${side}" type="number" min="20" step="1" value="${s.minutes??''}" placeholder="Required"></div><div class="field"><label for="matches-${side}">Matches played</label><input id="matches-${side}" type="number" min="1" max="6" step="1" value="${s.matches??''}" placeholder="Required"></div></div></div>`;}
function prediction(){
 if(!state.scenario)loadFixture(state.fixture);
 const s=state.scenario;
 main.innerHTML=head('PREDICTION LAB','Explore the match before the match.','Compare a ranking-based estimate with a model that also accounts for prior same-event workload.')+
 `<div class="prediction-top"><span class="filter-label">LOAD A VERIFIED FIXTURE</span><select id="fixture-select" aria-label="Load a verified fixture">${options([[-1,'Custom match scenario'],...D.fixtures.map((f,i)=>[i,f.name_a+' vs '+f.name_b+' · '+f.event])],state.fixture)}</select><button class="button small secondary" id="swap-players">${icon('swap')}Swap players</button><button class="button small secondary" id="reset-scenario">Reset example</button></div>
 <div class="prediction-grid"><section class="panel"><div class="section-head"><div><h2>Match inputs</h2><p>Use information available before the match.</p></div><span class="tag" id="scenario-tag">${state.fixture>=0?'Verified fixture':'Custom scenario'}</span></div>
 <div class="settings"><div class="field"><label for="pred-tour">Tour</label><select id="pred-tour">${options(['ATP','WTA'],s.tour)}</select></div><div class="field"><label for="pred-surface">Surface</label><select id="pred-surface">${options(['Hard','Clay','Grass'],s.surface)}</select></div><div class="field"><label for="pred-format">Match format</label><select id="pred-format">${options([[3,'Best of 3'],[5,'Best of 5']],s.bestOf)}</select></div><div class="field"><label for="pred-round">Round</label><select id="pred-round">${options([['R64','Round of 64'],['R32','Round of 32'],['R16','Round of 16'],['QF','Quarterfinal'],['SF','Semifinal'],['F','Final']],s.round)}</select></div></div>
 <datalist id="player-options">${D.players.filter(p=>p.tour===s.tour).map(p=>`<option value="${esc(p.player)}">${esc(p.country)} · Last rank ${p.rank??'unknown'}</option>`).join('')}</datalist><div class="player-fields">${playerForm('a')}${playerForm('b')}</div>
 <div class="form-bottom"><p>Both players need at least one prior main-draw match in this event. Estimates update as you change the inputs.</p><button class="button" id="calculate">${icon('spark')}Calculate probability</button></div><p class="status-detail">Selecting a player fills the last recorded rank and age, and clears event workload. Confirm each input for your match. Missing workload is never estimated automatically.</p></section>
 <aside class="prediction-side"><div id="prediction-result" aria-live="polite"></div><div class="panel sensitivity"><h3>What if the workload changes?</h3><p class="subtext">Player A win probability as prior minutes change. Other inputs stay fixed.</p><div id="sensitivity-chart"></div><p class="footnote">Sensitivity within the workload model. This is not a causal fatigue estimate.</p></div></aside></div>
 <div class="note-strip" style="margin-top:22px;margin-bottom:0">Research scope: standard knockout singles, with complete prior event workload. History ends 22 October 2026. The workload model has not shown a reliable predictive improvement. Exact rest, injury, travel, sleep, doubles and full qualifying workload are not modeled. Probabilities assume normal match completion.</div>`;
 $('#fixture-select').onchange=e=>{if(Number(e.target.value)>=0)loadFixture(Number(e.target.value));else state.fixture=-1;prediction();};
 $('#reset-scenario').onclick=()=>{loadFixture(3);prediction();};
 $('#swap-players').onclick=()=>{readScenario();[state.scenario.a,state.scenario.b]=[state.scenario.b,state.scenario.a];state.fixture=-1;prediction();};
 $('#calculate').onclick=()=>{readScenario();updatePrediction();notify(validate(state.scenario)||'Probabilities updated from the trained models.');};
 for(const control of $$('input,select',main).filter(e=>e.id!=='fixture-select')){
  control.addEventListener('input',()=>{state.fixture=-1;$('#fixture-select').value='-1';$('#scenario-tag').textContent='Custom scenario';readScenario();updatePrediction();});
 }
 for(const side of ['a','b'])$('#name-'+side).addEventListener('change',()=>{
   const player=D.players.find(p=>p.tour===$('#pred-tour').value&&p.player.toLowerCase()===$('#name-'+side).value.trim().toLowerCase());
   if(player){$('#rank-'+side).value=player.rank??'';$('#age-'+side).value=player.age??'';$('#qualifier-'+side).value='0';$('#profile-'+side).textContent='Last recorded: '+player.rank_date+'. Verify for your match.';}
   $('#minutes-'+side).value='';$('#matches-'+side).value='';readScenario();updatePrediction();
 });
 $('#pred-tour').addEventListener('change',()=>{state.scenario.tour=$('#pred-tour').value;for(const side of ['a','b'])state.scenario[side]={name:'',rank:null,age:null,qualifier:false,minutes:null,matches:null};state.fixture=-1;prediction();});
 updatePrediction();
}
function readScenario(){const num=id=>{const v=$('#'+id).value;return v===''?NaN:Number(v);};const s={tour:$('#pred-tour').value,surface:$('#pred-surface').value,bestOf:num('pred-format'),round:$('#pred-round').value};for(const side of ['a','b'])s[side]={name:$('#name-'+side).value.trim(),rank:num('rank-'+side),age:num('age-'+side),qualifier:!!num('qualifier-'+side),minutes:num('minutes-'+side),matches:num('matches-'+side)};state.scenario=s;return s;}
function updatePrediction(){
 const s=state.scenario,error=validate(s),el=$('#prediction-result');
 if(error){scenarioOutput=null;el.innerHTML=`<div class="result-card"><div class="eyebrow">COMPLETE THE MATCH INPUTS</div><h3>Ready when the data is.</h3><p class="result-error">${esc(error)}</p><p class="result-placeholder">Provide verified inputs to calculate both players' win probabilities.</p></div>`;$('#sensitivity-chart').innerHTML='<p class="footnote">Complete the inputs to explore this chart.</p>';return;}
 const result=predict(s,D.models);scenarioOutput=result;const pa=result.strength,preferred=pa>=.5?s.a.name:s.b.name,opponent=pa>=.5?s.b.name:s.a.name,win=pa>=.5?pa:1-pa;
 el.innerHTML=`<div class="result-card"><div class="eyebrow">BASELINE ESTIMATE</div><div class="result-status">${state.fixture>=0?'Frozen forecast · 23 Oct 2026':'Custom scenario · model snapshot 22 Oct 2026'}</div><div class="result-name">${esc(preferred)}</div><div class="result-prob">${(win*100).toFixed(1)}<small>%</small></div><div class="result-caption">Estimated win probability</div><div class="prob-track"><span style="width:${win*100}%"></span></div><div class="result-other"><span>${esc(opponent)}</span><strong>${pct(1-win)}</strong></div><div class="model-compare"><div><span>PLAYER A · BASELINE</span><strong>${pct(pa)}</strong></div><div><span>PLAYER A · + WORKLOAD</span><strong>${pct(result.strength_workload)}</strong></div></div><p class="status-detail" style="color:#adbf9f">Player A is ${esc(s.a.name)}. Both models were trained on the same eligible snapshot.</p><button class="button" id="export-prediction">${icon('download')}Export this prediction</button></div>`;
 $('#export-prediction').onclick=()=>{download('CourtEdge_match_prediction.json',JSON.stringify({created_at:new Date().toISOString(),data_cutoff:'2026-10-22',fixture_date:state.fixture>=0?'2026-10-23':null,type:state.fixture>=0?'frozen_fixture':'custom_scenario',inputs:s,probabilities:{baseline:{a:pa,b:1-pa},workload:{a:result.strength_workload,b:1-result.strength_workload}},scope:D.models.scope,caveat:'Association is not causation. Workload did not reliably improve held-out prediction. Conditional on standard match completion.'},null,2));notify('Prediction exported.');};
 sensitivity(s);
}
function sensitivity(s){const min=Math.max(s.a.matches*20,s.a.minutes-120),max=Math.min(s.a.matches*600,s.a.minutes+120),xs=Array.from({length:21},(_,i)=>min+(max-min)*i/20);const pts=xs.map(minutes=>({x:minutes,y:predict({...s,a:{...s.a,minutes}},D.models).strength_workload}));const low=Math.max(0,Math.floor((Math.min(...pts.map(p=>p.y))-.025)*20)/20),high=Math.min(1,Math.ceil((Math.max(...pts.map(p=>p.y))+.025)*20)/20);const fx=x=>33+(x-min)/(max-min||1)*220,fy=y=>118-(y-low)/(high-low||1)*90;const path=pts.map((p,i)=>(i?'L':'M')+fx(p.x).toFixed(2)+' '+fy(p.y).toFixed(2)).join(' ');const current=predict(s,D.models).strength_workload;$('#sensitivity-chart').innerHTML=`<svg viewBox="0 0 274 151" role="img" aria-label="Workload model: Player A probability decreases from ${pct(pts[0].y)} at ${Math.round(min)} minutes to ${pct(pts.at(-1).y)} at ${Math.round(max)} minutes"><line x1="33" y1="28" x2="253" y2="28" stroke="#e8eee1"/><line x1="33" y1="73" x2="253" y2="73" stroke="#e8eee1"/><line x1="33" y1="118" x2="253" y2="118" stroke="#e8eee1"/><g fill="#8b977c" font-size="8" font-family="Arial"><text x="1" y="31">${pct(high,0)}</text><text x="1" y="76">${pct((low+high)/2,0)}</text><text x="1" y="121">${pct(low,0)}</text><text x="33" y="140">${Math.round(min)} min</text><text x="253" y="140" text-anchor="end">${Math.round(max)} min</text></g><path d="${path}" fill="none" stroke="#6d9156" stroke-width="2.5"/><line x1="${fx(s.a.minutes)}" y1="28" x2="${fx(s.a.minutes)}" y2="118" stroke="#c6d4bc" stroke-dasharray="3 3"/><circle cx="${fx(s.a.minutes)}" cy="${fy(current)}" r="4" fill="#123d31" stroke="white" stroke-width="2"/></svg><p class="subtext">Current: <b>${s.a.minutes} min</b> · ${pct(current)} for Player A</p>`;}
function research(){
 main.innerHTML=head('RESEARCH & DATA','Transparent models. Open evidence.','Inspect the methods, compare test performance, and download the complete research snapshot.',`<a class="button" href="downloads/CourtEdge_2026_Data.zip" download>${icon('download')}Download all data</a>`)+
 `<div class="note-strip">The model measures workload proxies, not physiological fatigue. Source coverage ends 22 October 2026 and includes team-event singles. It does not represent the full season.</div>
 <div class="research-grid"><section class="panel"><div class="eyebrow">ADJUSTED ASSOCIATION</div><h2>One more hour on court</h2><div class="big-number">0.894 <span style="font-size:13px;color:#849079;letter-spacing:0">odds ratio</span></div><span class="confidence">95% interval · 0.825 to 0.984</span><p>Each additional prior hour relative to the opponent was associated with about <b>10.6% lower win odds</b>, after adjustment. This is not a 10.6 percentage point change in win probability.</p><p class="footnote">Prior match-count odds ratio: 1.084 (0.832-1.483). Development-set association; event-bootstrap intervals, 500 repetitions.</p></section>
 <section class="panel"><div class="eyebrow">INDEPENDENT TEST · 174 MATCHES</div><h2>Did workload improve the forecast?</h2><div class="table-scroll"><table class="research-model-table"><thead><tr><th>Model</th><th>AUC ↑</th><th>Log loss ↓</th><th>Brier ↓</th></tr></thead><tbody><tr><td>Baseline</td><td>0.671</td><td><b>0.6512</b></td><td>0.2297</td></tr><tr><td>+ Workload</td><td>0.660</td><td>0.6572</td><td>0.2323</td></tr></tbody></table></div><p>Both models achieved <b>60.9% accuracy</b>. Adding workload changed log loss by +0.0060, with a 95% interval of -0.0095 to +0.0272.</p><span class="tag warning">No reliable predictive improvement</span><p class="footnote">16 test events; 3,000 event-bootstrap repetitions. Lower log loss and Brier score are better.</p></section></div>
 <div class="section-head"><h2>How the study was built</h2><span class="card-count">1,578 eligible matches</span></div><div class="method-list"><section class="panel"><span class="method-index">01 / PRE-MATCH FEATURES</span><h3>Use only what was known</h3><p>Rank, age and qualifier status, with context interactions. The workload model adds earlier same-event hours and match counts. Current-match results and later rounds never become predictors.</p></section><section class="panel"><span class="method-index">02 / TIME-ORDERED EVALUATION</span><h3>Keep the test independent</h3><p>887 training, 187 validation and 174 test matches. A 21-day boundary buffer excludes another 330 eligible records from evaluation splits. The test begins with September events. Final forecast models use all 1,578 eligible records.</p></section><section class="panel"><span class="method-index">03 / REPRODUCIBLE EXECUTION</span><h3>Run and verify on Kaggle</h3><p>Regularized logistic regression. Private Kaggle notebook, version 1: successful CPU run in 55.7 seconds. Six code cells, no errors. Cloud and local metrics agreed within 10<sup>-12</sup>.</p><a class="text-action" href="https://www.kaggle.com/code/jerry871gws2/2026-tennis-fatigue-and-win-prediction" target="_blank" rel="noopener">Open Kaggle notebook ↗</a></section></div>
 <section class="panel" style="margin-bottom:24px"><h2>What the data can and cannot tell us</h2><p style="margin-top:12px;font-size:11px;line-height:1.9">Fatigue is not directly observed. Earlier opponent strength, injury, travel, sleep, training and scheduling can affect both time on court and outcomes. Qualifying and doubles are incompletely captured. Excluding retirements and missing durations can create selection bias. Source dates mix match-day and tournament-start meanings, so exact rest-day features are not used.</p><p style="margin-top:10px;font-size:11px;line-height:1.9">TennisStats integration verified official demo event 971951 against TennisMyLife (winner, two sets, 22 games) and matched four public fixtures. Full TennisStats history has not been imported; account access requires an API key. This site runs on the frozen dataset and does not claim a live connection.</p><div class="source-links"><a href="https://stats.tennismylife.org/tennis-match-database" target="_blank" rel="noopener">TennisMyLife database ↗</a><a href="https://tennisstats.com/" target="_blank" rel="noopener">TennisStats fixtures ↗</a><a href="https://tennisstats.com/api/documentations" target="_blank" rel="noopener">Official API documentation ↗</a></div></section>
 <div class="section-head"><div><h2>Data & downloads</h2><p>Original source fields, model features, predictions, code and the English report.</p></div><select id="download-category" aria-label="Download category">${options([['all','All files'],'Matches','Analysis','Raw source','Reproduce','Report','Code'],state.downloadCategory)}</select></div><div class="panel" id="download-list"></div><p class="footnote">Source data is provided for private research. Check the original providers' terms before redistribution. The complete archive also includes both models' coefficients, provenance and an English README.</p>`;
 renderDownloads();$('#download-category').onchange=e=>{state.downloadCategory=e.target.value;renderDownloads();};
}
function renderDownloads(){$('#download-list').innerHTML=D.downloads.filter(f=>state.downloadCategory==='all'||f.category===state.downloadCategory).map(f=>`<div class="download-row"><div><strong>${esc(f.name)}</strong><p>${esc(f.description)}</p><span class="file-size">${f.category} · ${f.bytes>=1e6?(f.bytes/1e6).toFixed(1)+' MB':Math.ceil(f.bytes/1000)+' KB'}</span></div><a class="button small secondary" href="downloads/${encodeURIComponent(f.name)}" download>${icon('download')}Download</a></div>`).join('');}
function render(){state.page=location.hash.slice(1)||'overview';if(!names[state.page])state.page='overview';$$('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===state.page);if(a.dataset.nav===state.page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#breadcrumb').textContent=names[state.page];document.title=names[state.page]+' | CourtEdge';({overview,matches,players,predict:prediction,research}[state.page])();window.scrollTo(0,0);}
$('#detail-dialog .close-dialog').onclick=()=>$('#detail-dialog').close();$('#detail-dialog').addEventListener('click',e=>{if(e.target===$('#detail-dialog'))$('#detail-dialog').close();});
try{
 const keys=['matches','players','fixtures','models','summary','downloads'];
 const results=await Promise.all(keys.map(async key=>{const r=await fetch(`data/${key}.json`);if(!r.ok)throw new Error('The '+key+' dataset could not be loaded.');return r.json();}));
 D=Object.fromEntries(keys.map((key,i)=>[key,results[i]]));
 loadFixture(3);window.addEventListener('hashchange',render);render();
}catch(error){main.innerHTML=`<div class="empty"><strong>Unable to load the research snapshot</strong><p>${esc(error.message)}</p><button class="button" style="margin-top:20px" id="reload">Try again</button></div>`;$('#reload').onclick=()=>location.reload();}
